"""Compare the outputs regenerated by reproduce_paper.sh with the committed versions (git index).

Text outputs must match exactly (after line-ending normalization). JSON outputs are compared
structurally: numbers within a relative tolerance of 1e-9 (last-digit float differences across CPUs
and BLAS builds), `generated_at` timestamps ignored. Exits non-zero and lists every mismatch.
usage: python scripts/check_reproduction.py
"""
import json
import math
import os
import subprocess
import sys

os.chdir(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))  # repo root
REL_TOL = 1e-9
IGNORED_KEYS = {"generated_at"}


def git(*args):
    return subprocess.run(["git", *args], check=True, capture_output=True, text=True).stdout


def same(a, b):
    if isinstance(a, dict) and isinstance(b, dict):
        keys = (set(a) | set(b)) - IGNORED_KEYS
        return all(k in a and k in b and same(a[k], b[k]) for k in keys)
    if isinstance(a, list) and isinstance(b, list):
        return len(a) == len(b) and all(same(x, y) for x, y in zip(a, b))
    if isinstance(a, (int, float)) and isinstance(b, (int, float)) and not isinstance(a, bool):
        return a == b or math.isclose(a, b, rel_tol=REL_TOL, abs_tol=1e-15)
    return a == b


changed = [p for p in git("diff", "--name-only", "--", "results", "analysis_manifest.json").split() if p]
bad = []
for path in changed:
    committed = git("show", f":{path}")  # index version (= HEAD in a fresh checkout)
    with open(path, encoding="utf-8") as fh:
        current = fh.read()
    if path.endswith(".json"):
        ok = same(json.loads(committed), json.loads(current))
    else:
        ok = committed.replace("\r\n", "\n") == current.replace("\r\n", "\n")
    print(("ok        " if ok else "MISMATCH  ") + path)
    if not ok:
        bad.append(path)
print(f"{len(changed)} changed file(s) checked, {len(bad)} mismatch(es)")
sys.exit(1 if bad else 0)
